def solve():
    best_n = 1
    best_error = abs(step_350(orbit_radius=orbit_radius, n=best_n)["orbit_kinetic_energy"] - KE)
    for candidate_n in range(2, 10001):
        candidate_error = abs(step_350(orbit_radius=orbit_radius, n=candidate_n)["orbit_kinetic_energy"] - KE)
        if candidate_error < best_error:
            best_n = candidate_n
            best_error = candidate_error

    best_Z = 1
    best_radius_error = abs(step_61(n=best_n, Z=best_Z)["orbit_radius"] - orbit_radius)
    for candidate_Z in range(2, 10001):
        candidate_radius_error = abs(step_61(n=best_n, Z=candidate_Z)["orbit_radius"] - orbit_radius)
        if candidate_radius_error < best_radius_error:
            best_Z = candidate_Z
            best_radius_error = candidate_radius_error

    return step_376(orbit_radius=orbit_radius, Z=best_Z, atoms=atoms)["potential_energy"]

